input.query:
select 'vault' as kind, name as label, created_at::text as detail from vault.secrets where name = 'ORMA_MATERIALISE_SECRET_KEY'
union all
select 'cron', jobname, schedule || ' active=' || active from cron.job;

select j.jobname, count(*) as runs_24h, max(d.start_time)::text as last_run, string_agg(distinct d.status, ',') as statuses, (select count(*) from net._http_response r where r.created > now() - interval '24 hours') as http_responses_24h
from cron.job_run_details d join cron.job j using (jobid)
where d.start_time > now() - interval '24 hours'
group by j.jobname;

select jobname, schedule, active from cron.job
union all
select 'fn:compute_pattern_facts', count(*)::text, true from pg_proc where proname = 'compute_pattern_facts';

